import React, { useEffect, useState } from "react";
import "../styles/subscriptions.css";

function Subscriptions() {
  const [channels, setChannels] = useState([]);
  const [selectedChannel, setSelectedChannel] = useState(null);
  const [articles, setArticles] = useState([]);
  const [polls, setPolls] = useState([]);
  const [error, setError] = useState(null);

  const token = localStorage.getItem("token");

  // Завантаження каналів
  useEffect(() => {
    const fetchChannels = async () => {
      try {
        const res = await fetch("http://127.0.0.1:8000/api/channels/", {
          headers: {
            "Content-Type": "application/json",
            ...(token && { Authorization: `Bearer ${token}` }),
          },
        });

        if (!res.ok) throw new Error("Помилка завантаження каналів");

        const data = await res.json();
        setChannels(Array.isArray(data) ? data : data.results || []);
        console.log("Channels loaded:", data);
      } catch (err) {
        console.error(err);
        setError("Не вдалося завантажити канали");
      }
    };

    fetchChannels();
  }, [token]);

  // Відкрити статті і опитування каналу
  const openChannel = async (channelId) => {
    setSelectedChannel(channelId);

    try {
      // Статті
      const resArticles = await fetch(
        `http://127.0.0.1:8000/api/channels/${channelId}/articles/`,
        {
          headers: {
            "Content-Type": "application/json",
            ...(token && { Authorization: `Bearer ${token}` }),
          },
        }
      );
      if (!resArticles.ok) throw new Error("Не вдалося завантажити статті каналу");
      const dataArticles = await resArticles.json();
      setArticles(Array.isArray(dataArticles) ? dataArticles : dataArticles.results || []);

      // Опитування
      const resPolls = await fetch(
        `http://127.0.0.1:8000/api/channels/${channelId}/polls/`,
        {
          headers: {
            "Content-Type": "application/json",
            ...(token && { Authorization: `Bearer ${token}` }),
          },
        }
      );
      if (!resPolls.ok) throw new Error("Не вдалося завантажити опитування каналу");
      const dataPolls = await resPolls.json();
      setPolls(Array.isArray(dataPolls) ? dataPolls : dataPolls.results || []);

      console.log(`Articles for channel ${channelId}:`, dataArticles);
      console.log(`Polls for channel ${channelId}:`, dataPolls);

    } catch (err) {
      console.error(err);
      setError(err.message);
      setArticles([]);
      setPolls([]);
    }
  };

  // Підписка / Відписка
  const toggleSubscription = async (channelId, isSubscribed) => {
    try {
      const url = `http://127.0.0.1:8000/api/channels/${channelId}/${
        isSubscribed ? "unsubscribe" : "subscribe"
      }/`;
      const res = await fetch(url, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          ...(token && { Authorization: `Bearer ${token}` }),
        },
      });

      if (!res.ok) throw new Error("Помилка підписки");

      setChannels((prev) =>
        prev.map((ch) =>
          ch.id === channelId ? { ...ch, is_subscribed: !isSubscribed } : ch
        )
      );
    } catch (err) {
      console.error(err);
      setError(err.message);
    }
  };

  return (
    <div className="subscriptions-container">
      <h2>Підписки</h2>
      {error && <p className="error">{error}</p>}

      {!selectedChannel ? (
        <>
          {channels.length === 0 ? (
            <p>Поки немає каналів</p>
          ) : (
            <ul className="channel-list">
              {channels.map((ch) => (
                <li key={ch.id} className="channel-item">
                  <span
                    className="channel-name"
                    onClick={() => openChannel(ch.id)}
                  >
                    {ch.name || "Без назви"}
                  </span>
                  <button
                    className={`subscribe-btn ${
                      ch.is_subscribed ? "unsubscribe" : "subscribe"
                    }`}
                    onClick={() => toggleSubscription(ch.id, ch.is_subscribed)}
                  >
                    {ch.is_subscribed ? "Відписатись" : "Підписатись"}
                  </button>
                </li>
              ))}
            </ul>
          )}
        </>
      ) : (
        <div>
          <button className="back-btn" onClick={() => setSelectedChannel(null)}>
            ← Назад
          </button>

          <h3>Статті каналу</h3>
          {articles.length === 0 ? (
            <p>У цього каналу поки немає статей.</p>
          ) : (
            <div className="articles-list">
              {articles.map((a) => (
                <div key={a.id} className="article-card">
                  {a.image && (
                    <img
                      src={a.image.startsWith("http") ? a.image : `http://127.0.0.1:8000${a.image}`}
                      alt={a.title}
                      className="article-image"
                    />
                  )}
                  <div className="article-content">
                    <h4 className="article-title">{a.title || "(Без назви)"}</h4>
                    <p className="article-author">Автор: {a.author_name || "Невідомий"}</p>
                    {a.category && <p className="article-category">Категорія: {a.category}</p>}
                    {a.channel && <p className="article-channel">Канал: {a.channel}</p>}
                    {a.created_at && (
                      <p className="article-date">
                        Опубліковано: {new Date(a.created_at).toLocaleDateString("uk-UA")}
                      </p>
                    )}
                    <p className="article-text">{a.content || "(Без контенту)"}</p>
                  </div>
                </div>
              ))}
            </div>
          )}

          <h3>Опитування каналу</h3>
          {polls.length === 0 ? (
            <p>У цього каналу поки немає опитувань.</p>
          ) : (
            <ul className="polls-list">
              {polls.map((p) => (
                <li key={p.id}>
                  <strong>{p.question}</strong>
                  {p.choices?.map((c) => (
                    <div key={c.id} style={{ marginLeft: "15px" }}>
                      {c.text} ({c.votes} голосів)
                    </div>
                  ))}
                </li>
              ))}
            </ul>
          )}
        </div>
      )}
    </div>
  );
}

export default Subscriptions;
